```cpp
void QFileDialog::setSidebarUrls(const QList<QUrl> &urls)
{
    Q_D(QFileDialog);
    if (!d->nativeDialogInUse)
        d->qFileDialogUi->sidebar->setUrls(urls);
}
```

Source: https://codebrowser.dev/qt6/qtbase/src/widgets/dialogs/qfiledialog.cpp.html

